// lib/account.ts
import { unstable_cache } from 'next/cache';
import { getSession } from './session'; // reads the request cookie via cookies()

export async function getAccountSummary() {
  const session = await getSession();
  const cached = unstable_cache(
    async () => db.account.summary(session.userId), // closure capture
    ['account-summary'],
    { revalidate: 600 },
  );
  return cached();
}

// 10:00 Alice opens /account (cache empty)
// 10:03 Bob opens /account
// 10:12 Carol opens /account

