// lib/account.ts
import { unstable_cache } from 'next/cache';
import { getSession } from './session'; // читает cookie запроса через cookies()

export async function getAccountSummary() {
  const session = await getSession();
  const cached = unstable_cache(
    async () => db.account.summary(session.userId), // захват замыканием
    ['account-summary'],
    { revalidate: 600 },
  );
  return cached();
}

